DEPOT_ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}

DELIMS = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
BASE_DATE = {'east': 'ymd', 'lakeside': 'iso', 'harbor': 'iso', 'river': 'mm/dd/yyyy',
             'west': 'dd.mm.yyyy'}
DECIMAL_COMMA = {'west'}
GROUP_COMMA_DEPOTS = {'east'}
COLUMNS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
FW_LAYOUTS = {
    'FW1': dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), date='yyyyddd', unit='g', scale=Fraction(1)),
    'FW2': dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), date='yyyymmdd', unit='kg', scale=Fraction(1, 100)),
    'FW3': dict(length=41, id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24),
                status=(24, 25), date='yyyyddd', unit='lb', scale=Fraction(1, 10)),
}
FW_STATUS = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned',
             'H': 'held'}


# ---------------------------------------------------------------- bytes/text

def read_bytes(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode_text(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', errors='replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', errors='replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', errors='replace')
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w.-]+)', head, re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1), errors='replace')
        except LookupError:
            return b.decode('latin-1')
    return b.decode('utf-8', errors='replace')


def text_lines(text):
    lines = text.split('\n')
    return [l[:-1] if l.endswith('\r') else l for l in lines]


# ---------------------------------------------------------------- values

def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(status):
    return status in ('delivered', 'delivered_late')


def norm_id(s):
    m = re.search(r'[Ss][Hh]\D*?(\d+)', s or '')
    return int(m.group(1)) if m else None


def rec_type(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'correction'
    return 'new'


def parse_number(s, decimal_comma=False, group_comma=True):
    s = s.strip().replace(' ', '').replace(' ', '').replace("'", '')
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(Decimal(s))


def parse_weight(value, unit_chain, decimal_comma=False):
    """value: text; unit_chain: units in decreasing priority (None skipped)."""
    s = (value or '').strip()
    m = re.match(r'^([-+\d.,\s]+?)\s*([A-Za-z]+)$', s)
    unit = None
    if m and m.group(2).lower() in UNITS:
        s, unit = m.group(1), m.group(2).lower()
    if unit is None:
        for u in unit_chain:
            if u:
                unit = u
                break
    if unit is None:
        unit = 'kg'
    return parse_number(s, decimal_comma) * UNIT_KG[unit]


def clean_unit(s):
    if not s:
        return None
    m = re.match(r'\s*([A-Za-z]+)', s)
    if m and m.group(1).lower() in UNITS:
        return m.group(1).lower()
    return None


def to_date(s, form):
    s = s.strip()
    f = (form or '').strip().lower()
    f = re.sub(r'\s+', '', f)
    if f in ('serial',):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    if f in ('yyyyddd',):
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
    if f in ('yyyymmdd',):
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$', s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    nums = re.findall(r'\d+', s)
    if f in ('iso', 'ymd', 'yyyy-mm-dd'):
        return date(int(nums[0]), int(nums[1]), int(nums[2]))
    if f in ('dmy', 'dd-mm-yyyy', 'dd/mm/yyyy', 'dd.mm.yyyy'):
        return date(int(nums[2]), int(nums[1]), int(nums[0]))
    if f in ('mdy', 'mm/dd/yyyy', 'mm-dd-yyyy'):
        return date(int(nums[2]), int(nums[0]), int(nums[1]))
    # unknown form: guess
    if len(nums[0]) == 4:
        return date(int(nums[0]), int(nums[1]), int(nums[2]))
    return date(int(nums[2]), int(nums[1]), int(nums[0]))


def ship_date(s, form):
    """Return the UTC date of a ship date or ship time."""
    s = s.strip()
    if re.match(r'^\d{4}-\d{2}-\d{2}[T ]\d', s):
        t = s.replace(' ', 'T', 1)
        if t.endswith(('Z', 'z')):
            t = t[:-1] + '+00:00'
        t = re.sub(r'([+-]\d{2})(\d{2})$', r'\1:\2', t)
        dt = datetime.fromisoformat(t)
        if dt.tzinfo is None:
            return dt.date()
        return dt.astimezone(timezone.utc).date()
    return to_date(s, form)


def mk(rtype, num, status=None, kg=None, d=None):
    return {'type': rtype, 'num': num, 'status': status, 'kg': kg, 'date': d}


# ---------------------------------------------------------------- parsers

def logical_rows(lines, quoted):
    """Yield (is_comment, text) records; quoted fields can span lines."""
    buf = None
    for l in lines:
        if buf is not None:
            buf += '\n' + l
            if buf.count('"') % 2 == 0:
                yield False, buf
                buf = None
            continue
        if l.startswith('#'):
            yield True, l
            continue
        if not l.strip():
            continue
        if quoted and l.count('"') % 2 == 1:
            buf = l
            continue
        yield False, l
    if buf is not None:
        yield False, buf


def split_row(r, delim, quoted):
    if quoted:
        return next(csv.reader([r], delimiter=delim))
    return r.split(delim)


def is_weight_col(name):
    return re.match(r'^(gross|weight)(_(kg|g|lb|oz))?$', name) is not None


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    quoted = delim == ','
    lines = text_lines(text)
    seq = None
    dirs = {}
    header = None
    recs = []
    known = COLUMNS[depot]
    for is_c, r in logical_rows(lines, quoted):
        if is_c:
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*?)\s*$', r)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).strip().lower())
                dirs[name] = m.group(2)
                if name == 'seq' and seq is None:
                    try:
                        seq = int(m.group(2))
                    except ValueError:
                        pass
                continue
            m = re.search(r'\bseq\s*=\s*(\d+)', r)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        f = split_row(r, delim, quoted)
        names = [x.strip().lower() for x in f]
        if all(n in known or is_weight_col(n) for n in names) and any(n in known for n in names):
            header = names
            continue
        if header is None:
            header = list(sorted_default(depot))
        extra_unit = None
        wi = next((i for i, n in enumerate(header) if is_weight_col(n)), None)
        if len(f) == len(header) + 1 and wi is not None and f[wi + 1].strip().lower() in UNITS:
            extra_unit = f[wi + 1].strip().lower()
            del f[wi + 1]
        row = dict(zip(header, f))
        idk = next((k for k in ('id', 'ref') if k in row), None)
        num = norm_id(row.get(idk, ''))
        if num is None:
            continue
        tk = next((k for k in ('type', 'kind', 'rec', 't', 'typ') if k in row), None)
        rt = rec_type(row.get(tk, ''))
        if rt == 'void':
            recs.append(mk('void', num))
            continue
        sk = next((k for k in ('status', 'state') if k in row), None)
        dk = next((k for k in ('shipped', 'date') if k in row), None)
        wname = header[wi] if wi is not None else None
        name_unit = None
        if wname:
            m = re.search(r'_(kg|g|lb|oz)$', wname)
            name_unit = m.group(1) if m else None
        dir_unit = clean_unit(dirs.get('unit') or dirs.get('weight unit'))
        dec_comma = depot in DECIMAL_COMMA
        wu = dirs.get('weight unit', '')
        if 'decimal comma' in wu.lower():
            dec_comma = True
        elif 'decimal point' in wu.lower() or 'decimal dot' in wu.lower():
            dec_comma = False
        form = (dirs.get('dates') or dirs.get('date format') or dirs.get('date')
                or BASE_DATE[depot])
        status = norm_status(STATE_CODES.get(row.get(sk, '').strip().upper(), row.get(sk, '')))
        kg = parse_weight(row.get(wname, ''), [name_unit, extra_unit, dir_unit], dec_comma)
        d = ship_date(row[dk], form)
        recs.append(mk(rt, num, status, kg, d))
    return seq, recs


STATE_CODES = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
               'RET': 'returned', 'HLD': 'held'}


def sorted_default(depot):
    return {
        'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
        'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
        'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
        'river': ['t', 'ref', 'shipped', 'weight', 'status'],
        'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
    }[depot]


def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    for l in text_lines(text):
        if '\x0c' in l or l.startswith('SOUTH DEPOT'):
            continue
        if l.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\S+)', l)
            if m and m.group(1) in FW_LAYOUTS:
                layout = m.group(1)
                continue
            m = re.match(r'^#SEQ\s+(\d+)', l)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not l.strip():
            continue
        name = layout
        for k, v in FW_LAYOUTS.items():
            if v['length'] == len(l):
                name = k
        if name is None:
            continue
        L = FW_LAYOUTS[name]
        if len(l) < L['length']:
            l = l.ljust(L['length'])

        def fld(k):
            a, b = L[k]
            return l[a:b]
        num = norm_id(fld('id'))
        if num is None:
            continue
        rt = rec_type(fld('type'))
        if rt == 'void':
            recs.append(mk('void', num))
            continue
        kg = Fraction(int(fld('weight'))) * L['scale'] * UNIT_KG[L['unit']]
        status = FW_STATUS.get(fld('status').strip().upper(), 'other')
        recs.append(mk(rt, num, status, kg, to_date(fld('shipped'), L['date'])))
    return seq, recs


def parse_json(text):
    seq = None
    recs = []
    meta_unit = None
    for l in text_lines(text):
        if not l.strip():
            continue
        try:
            v = json.loads(l)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                meta_unit = clean_unit(str(o['meta'].get('unit') or o['meta'].get('weight_unit') or ''))
                continue
            num = norm_id(str(o.get('id', '')))
            if num is None:
                continue
            rt = rec_type(o.get('kind', ''))
            if rt == 'void':
                recs.append(mk('void', num))
                continue
            wk = next((k for k in o if re.match(r'^weight_(kg|g|lb|oz)$', k)), None)
            name_unit = None
            if wk:
                name_unit = wk.split('_')[1]
            else:
                wk = 'weight'
            val = o.get(wk)
            kg = parse_weight(str(val), [name_unit, clean_unit(str(o.get('unit') or '')), meta_unit])
            recs.append(mk(rt, num, norm_status(o.get('status')), kg,
                           ship_date(str(o['shipped_at']), 'iso')))
    return seq, recs


def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') and root.get('seq').strip().isdigit() else None
    root_unit = clean_unit(root.get('weight-unit') or root.get('weight_unit'))
    recs = []

    def val(e, name):
        if e.get(name) is not None:
            return e.get(name)
        c = e.find(name)
        return c.text if c is not None and c.text is not None else None
    for e in root.iter('shipment'):
        num = norm_id(e.get('id') or val(e, 'id') or '')
        if num is None:
            continue
        rt = rec_type(e.get('type') or '')
        if rt == 'void':
            recs.append(mk('void', num))
            continue
        w = e.find('weight')
        if w is not None:
            wtext = w.text or ''
            wunit = clean_unit(w.get('unit'))
        else:
            wtext = e.get('weight') or ''
            wunit = clean_unit(e.get('unit'))
        kg = parse_weight(wtext, [wunit, clean_unit(e.get('weight-unit')), root_unit])
        recs.append(mk(rt, num, norm_status(val(e, 'status')), kg,
                       ship_date(val(e, 'shipped'), 'iso')))
    return seq, recs


def load(path, depot):
    b = read_bytes(path)
    stripped = b.lstrip(b'\xef\xbb\xbf \t\r\n')
    if depot == 'central' or stripped[:1] == b'<':
        return parse_xml(b)
    text = decode_text(b)
    if depot == 'north':
        return parse_json(text)
    if depot == 'south':
        return parse_fixed(text)
    return parse_delimited(depot, text)


# ---------------------------------------------------------------- main

def main(data_dir, out_file):
    files = sorted(f for f in os.listdir(data_dir)
                   if os.path.isfile(os.path.join(data_dir, f)))
    exports = {}
    for f in files:
        depot = f.split('-', 1)[0].lower()
        seq, recs = load(os.path.join(data_dir, f), depot)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, f, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        exps.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in exps:
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    def rank(d):
        return (DEPOT_ORDER.index(d), d) if d in DEPOT_ORDER else (len(DEPOT_ORDER), d)
    owners = {}
    for depot in sorted(current, key=rank):
        for n, r in current[depot].items():
            owners.setdefault(n, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for n, v in owners.items():
        depot, r = v[0]
        if not counted(r['status']):
            continue
        depots[depot][0] += 1
        depots[depot][1] += r['kg']
        key = '%04d-%02d' % (r['date'].year, r['date'].month)
        m = months.setdefault(key, [0, Fraction(0)])
        m[0] += 1
        m[1] += r['kg']

    def rnd(x):
        d = Decimal(x.numerator) / Decimal(x.denominator)
        return float(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': c, 'total_kg': rnd(w)} for d, (c, w) in depots.items()},
        'months': {k: {'shipments': months[k][0], 'total_kg': rnd(months[k][1])}
                   for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
